long long jobScheduling(vector<int>& s, vector<int>& e, vector<int>& p) {
    int n = s.size(); vector<array<long long,3>> j(n); for (int i = 0; i < n; i++) j[i] = {e[i], s[i], p[i]}; sort(j.begin(), j.end());
    vector<long long> ends(n), dp(n + 1, 0); for (int i = 0; i < n; i++) ends[i] = j[i][0];
    for (int i = 0; i < n; i++) { int k = upper_bound(ends.begin(), ends.begin() + i, j[i][1]) - ends.begin(); dp[i+1] = max(dp[i], dp[k] + j[i][2]); }
    return dp[n];
}
